import pathlib,subprocess,json
home=pathlib.Path('/home/appontrack/ontrack-voice-link')
marker='# ontrack-voice-link'
if not home.is_dir(): raise RuntimeError('host_link_home_missing')
read=subprocess.run(['crontab','-l'],capture_output=True,text=True,timeout=8)
if read.returncode not in (0,1):raise RuntimeError('crontab_unreadable')
if read.returncode==1 and 'no crontab' not in read.stderr.lower():raise RuntimeError('crontab_unreadable')
old=read.stdout.splitlines() if read.returncode==0 else []
removed=[line for line in old if marker in line]
preserved=[line for line in old if marker not in line]
if removed:
 result=subprocess.run(['crontab','-'],input='\n'.join(preserved)+'\n',capture_output=True,text=True,timeout=8)
 if result.returncode!=0:raise RuntimeError('crontab_disable_failed')
verify=subprocess.run(['crontab','-l'],capture_output=True,text=True,timeout=8)
if verify.returncode not in (0,1):raise RuntimeError('crontab_verify_failed')
if marker in verify.stdout:raise RuntimeError('host_link_cron_still_active')
stop=home/'STOP'
stop.touch(exist_ok=True)
print(json.dumps({'disabled':True,'cron_entries_removed':len(removed),'stop_file':str(stop),'other_cron_entries_preserved':len(preserved),'site_or_apk_touched':False},separators=(',',':')))
